INSERT INTO LOAN_PRODUCT (PRODUCT_ID, PRODUCT_CODE, PROVIDER_NAME, PRODUCT_NAME, PRODUCT_TYPE_NAME, SUMMARY, DESCRIPTION, RATE_MIN_PCT, RATE_MAX_PCT, LIMIT_MAX_AMT, TERM_MIN_MONTHS, TERM_MAX_MONTHS, TERM_TEXT, REPAYMENT_METHOD, MIN_ALT_SCORE, ELIGIBILITY_TEXT, REQUIRED_DOCUMENTS, CAUTION_TEXT, DUMMY_YN, BASE_DATE) VALUES (14, 'LP014', '가상카드 B', '빠른 카드론', '카드론', '급할 때 비교해 보는 시연용 카드론입니다.', '급하게 자금이 필요한 상황을 가정한 카드론 예시입니다.'||CHR(10)||'상환 기간이 짧은 만큼 이자 부담과 만기 일정을 먼저 따져 보아야 하는 상품입니다.'||CHR(10)||'시연용 수치로 금리는 연 7.15~19.32%, 한도는 최대 3,600만 원, 기간은 2~36개월입니다.', 7.15, 19.32, 36000000, 2, 36, '2~36개월(시연)', '만기일시', 0, '모든 직군 대상(시연용)', '신분증 사본·카드 이용 내역', '더미 상품 · 실제 상품 아님', 'Y', DATE '2026-09-18');
INSERT INTO LOAN_PRODUCT (PRODUCT_ID, PRODUCT_CODE, PROVIDER_NAME, PRODUCT_NAME, PRODUCT_TYPE_NAME, SUMMARY, DESCRIPTION, RATE_MIN_PCT, RATE_MAX_PCT, LIMIT_MAX_AMT, TERM_MIN_MONTHS, TERM_MAX_MONTHS, TERM_TEXT, REPAYMENT_METHOD, MIN_ALT_SCORE, ELIGIBILITY_TEXT, REQUIRED_DOCUMENTS, CAUTION_TEXT, DUMMY_YN, BASE_DATE) VALUES (15, 'LP015', '가상카드 C', '유연 카드론', '카드론', '상환 기간을 비교해 보는 시연용 카드론입니다.', '상환 기간에 따라 부담이 어떻게 달라지는지 비교해 보도록 만든 카드론 예시입니다.'||CHR(10)||'같은 카드론 가운데 한도가 가장 높게 설정되어 있어 조건 차이를 확인하기 좋습니다.'||CHR(10)||'시연용 수치로 금리는 연 6.96~19.51%, 한도는 최대 4,600만 원, 기간은 2~36개월입니다.', 6.96, 19.51, 46000000, 2, 36, '2~36개월(시연)', '만기일시', 0, '모든 직군 대상(시연용)', '신분증 사본·카드 이용 내역', '더미 상품 · 실제 상품 아님', 'Y', DATE '2026-09-18');
INSERT INTO LOAN_PRODUCT (PRODUCT_ID, PRODUCT_CODE, PROVIDER_NAME, PRODUCT_NAME, PRODUCT_TYPE_NAME, SUMMARY, DESCRIPTION, RATE_MIN_PCT, RATE_MAX_PCT, LIMIT_MAX_AMT, TERM_MIN_MONTHS, TERM_MAX_MONTHS, TERM_TEXT, REPAYMENT_METHOD, MIN_ALT_SCORE, ELIGIBILITY_TEXT, REQUIRED_DOCUMENTS, CAUTION_TEXT, DUMMY_YN, BASE_DATE) VALUES (16, 'LP016', '가상캐피탈 A', '캐피탈 신용대출 스탠다드', '캐피탈 신용대출', '할부·리스 금융사를 가정한 시연용 신용대출입니다.', '할부와 리스를 다루는 금융사를 가정한 캐피탈 신용대출 예시입니다.'||CHR(10)||'원금을 매달 같은 금액씩 갚는 방식이며 금리 범위가 높은 편이라 상환 계획을 먼저 확인해야 합니다.'||CHR(10)||'시연용 수치로 금리는 연 9.46~19.44%, 한도는 최대 4,600만 원, 기간은 12~60개월입니다.', 9.46, 19.44, 46000000, 12, 60, '12~60개월(시연)', '원금균등', 0, '모든 직군 대상(시연용)', '신분증 사본·소득 증빙', '더미 상품 · 실제 상품 아님', 'Y', DATE '2026-09-18');
